#include <iostream>
using namespace std;

int main() {
    double fuel = 7.5;
    double rate = 2.0;
    double burn_time = fuel / rate;

    cout << "FLOAT BYTES: " << sizeof(float) << endl;
    cout << "DOUBLE BYTES: " << sizeof(double) << endl;
    cout << "BURN TIME: " << burn_time << " S" << endl;
    return 0;
}

